after:
  platform = "linux",
  runtimeDir = "/run/user/1",
  managerAvailable = true,
}: {
  readonly oomPolicy?: boolean;
  readonly stopFails?: boolean;
  readonly platform?: NodeJS.Platform;
  readonly runtimeDir?: string;
  readonly managerAvailable?: boolean;
} = {},

const foreignSlice = ownedAgentSlice(`${stateDir}-foreign-project`);
units.set(foreignSlice, { activeState: "active", result: "success" });
units.set("app-t3code-agents.slice", { activeState: "active", result: "success" });

expect(sliceOf(terminal)).toBe(ownedAgentSlice(stateDir).replace(/-agents\.slice$/, ".slice"));
expect(sliceOf(terminal)).not.toBe(sliceOf(agent));
expect(calls.filter(([, verb]) => verb === "set-property").map((args) => args[3]))
  .toEqual([sliceOf(terminal)]);
expect(calls.some((args) => args.includes(foreignSlice) || args.includes("app-t3code-agents.slice")))
  .toBe(false);

const foreignUnit = "t3code-muse-foreign-project.scope";
exitedAgent(units, cgroupRoot, foreignUnit, { populated: true, oomKills: 0 });
yield* scope.stop(foreignUnit);
expect(calls.some((args) => args.includes(foreignUnit))).toBe(false);

it.effect("finalizes only issued nonpersistent units while retaining native OOM diagnosis", () =>
  withFakeSystemd(({ scope, units, calls, cgroupRoot, closeNativeScope }) => Effect.gen(function* () {
    const agent = yield* scope.wrap({ command: "agent", args: [], name: "t", threadId: "a" });
    const shared = yield* scope.wrap({ command: "agent", args: [], name: "shared", shared: true });
    const terminal = yield* scope.wrap({ command: "agent", args: [], name: "terminal", survivesRestart: true });
    const oom = yield* scope.wrap({ command: "agent", args: [], name: "oom", threadId: "oom" });
    for (const launch of [agent, shared, terminal]) {
      exitedAgent(units, cgroupRoot, unitOf(launch), { populated: true, oomKills: 0 });
    }
    exitedAgent(units, cgroupRoot, unitOf(oom), { populated: true, oomKills: 1 });
    exitedAgent(units, cgroupRoot, "t3code-foreign.scope", { populated: true, oomKills: 0 });
    yield* closeNativeScope;
    expect(stopsOf(calls)).toEqual([
      ["--user", "stop", "--no-block", unitOf(agent)],
      ["--user", "stop", "--no-block", unitOf(shared)],
    ]);
    expect(calls.some((args) => args.includes("t3code-foreign.scope"))).toBe(false);
  })),
);

it.effect("does not claim a native unit when the Linux user manager is unavailable", () =>
  withFakeSystemd(({ scope, calls }) => Effect.gen(function* () {
    const launch = yield* scope.wrap({ command: "agent", args: ["hello"], name: "t", threadId: "a" });
    expect(launch.command).toBe("/bin/sh");
    expect(launch.unit).toBeUndefined();
    expect(launch.args).toContain("hello");
    expect(launch.args.some((arg) => arg.startsWith("--unit="))).toBe(false);
    yield* scope.stop("t3code-foreign.scope");
    expect(stopsOf(calls)).toEqual([]);
    expect(yield* scope.oomKilled("a")).toBe(false);
  }), { managerAvailable: false }),
);

it.effect("does not probe systemd without the bound runtime directory", () =>
  withFakeSystemd(({ scope, calls }) => Effect.gen(function* () {
    const launch = yield* scope.wrap({ command: "agent", args: [], name: "t" });
    expect(launch.unit).toBeUndefined();
    expect(calls).toEqual([]);
  }), { runtimeDir: "" }),
);

it.effect.each(["darwin", "win32"] as const)("leaves native wrapping unavailable on %s", (platform) =>
  withFakeSystemd(({ scope, calls }) => Effect.gen(function* () {
    const launch = yield* scope.wrap({ command: "agent", args: ["native"], name: "t" });
    expect(launch).toEqual({ command: "agent", args: ["native"] });
    yield* scope.stop("t3code-foreign.scope");
    expect(calls).toEqual([]);
  }), { platform }),
);
